package com.xiaoxiaoshuo.reader;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public class InfoActivity extends Activity{private final int green=Color.rgb(49,88,71);@Override public void onCreate(Bundle b){super.onCreate(b);String mode=getIntent().getStringExtra("mode");if(mode==null)mode="settings";build(mode);}private void build(String mode){String title,body;if(mode.equals("help")){title="帮助中心";body="搜索书籍\n在首页搜索框输入书名或作者，应用会使用智能筛选的80个优质书源并发检索。\n\n目录与章节\n点击搜索结果进入详情页，先加载书籍详情，再加载完整目录。目录每次显示80章，可继续点击“加载更多章节”。\n\n封面加载\n优先使用书源返回的真实封面；遇到防盗链或无封面时自动显示文艺插画默认封面。\n\n书源管理\n在“我的 → 书源管理”可以查看智能80书源，也可以粘贴JSON、JSON数组或订阅网址添加更多。\n\n阅读失败\n某个书源章节失效时，返回搜索结果选择同一本书的其他来源即可。";}else if(mode.equals("disclaimer")){title="免责声明";body="小小说本身不提供、存储或销售第三方小说内容。外部书源由用户自行导入或从旧版本保留，应用仅按照书源规则访问公开可访问的页面。\n\n请只使用你有权访问的内容，并遵守内容提供方的服务条款、版权规则及所在地法律。应用不提供付费墙绕过、账号鉴权绕过、DRM破解或受保护内容的解密功能。\n\n书源失效、内容缺失、封面防盗链或第三方网站变更，均可能导致搜索或阅读不可用。";}else{title="设置";body="阅读设置已移动到阅读页右上角 Aa。\n\n当前固定配置\n• 永久 AI 排版\n• 智能优选80个书源\n• 封面自动缓存与文艺默认封面\n• 华为兼容参数 minSdk 23 / targetSdk 29\n\n如果旧版书源仍在应用数据库里，会自动恢复，不会主动清空。";}LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,244,238));root.setPadding(dp(18),dp(10),dp(18),dp(24));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView back=tx("‹",32,green,true);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(44),dp(50)));top.addView(tx(title,22,Color.rgb(43,55,49),true),new LinearLayout.LayoutParams(0,dp(50),1));root.addView(top);ScrollView sv=new ScrollView(this);LinearLayout card=new LinearLayout(this);card.setPadding(dp(18),dp(18),dp(18),dp(18));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(20));card.setBackground(g);TextView text=tx(body,15,Color.rgb(70,69,65),false);text.setLineSpacing(dp(6),1f);card.addView(text);sv.addView(card);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);getWindow().setStatusBarColor(Color.rgb(247,244,238));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);}private TextView tx(String s,int z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.create("sans",b?Typeface.BOLD:Typeface.NORMAL));return v;}private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}}